// Build the local browser-test database (e2e/supabase/migrations) from
// production's schema. Run after a production schema change you want the
// browser tests to cover; commit the regenerated files.
//
// Inputs (read-only exports from production, made with a Supabase CLI workdir
// linked to production — never this checkout, which stays linked to staging):
//   npx supabase db dump --linked --workdir <prod-dir> -f prod-schema.sql
//   npx supabase db query --linked --workdir <prod-dir> -o json "<reference query below>" > prod-reference.json
//
//   node scripts/e2e/build-db.mjs prod-schema.sql prod-reference.json
//
// The reference export holds only global, non-customer rows: the report
// catalog (portfolio_id is null), feature entitlements and collection-law
// profiles. (Maintenance templates are left out: they reference template
// groups the tests don't use.)
//   select jsonb_build_object(
//     'report_definitions', (select jsonb_agg(to_jsonb(t)) from report_definitions t where portfolio_id is null),
//     'feature_entitlements', (select jsonb_agg(to_jsonb(t)) from feature_entitlements t),
//     'collection_jurisdiction_profiles', (select jsonb_agg(to_jsonb(t)) from collection_jurisdiction_profiles t)
//   ) as d
import { readFileSync, writeFileSync } from 'node:fs';

const [schemaFile, referenceFile] = process.argv.slice(2);
if (!schemaFile || !referenceFile) throw new Error('Usage: node scripts/e2e/build-db.mjs <prod-schema.sql> <prod-reference.json>');
const OUT = 'e2e/supabase/migrations';

// 1. Schema. Scheduled jobs are not part of the test database: tests call the
//    same functions directly, and a local pg_cron must not email anyone.
const schema = readFileSync(schemaFile, 'utf8');
writeFileSync(`${OUT}/00000000000000_production_schema.sql`,
  `-- Production schema (structure only, no data), dumped ${new Date().toISOString().slice(0, 10)}.\n-- Generated by scripts/e2e/build-db.mjs. Do not edit by hand.\n\n${schema}`);

// 2. Reference rows.
const text = readFileSync(referenceFile, 'utf8');
const ref = JSON.parse(text.slice(text.indexOf('{'), text.lastIndexOf('}') + 1)).rows[0].d;
const literal = (v) => `'${JSON.stringify(v).replace(/'/g, "''")}'::jsonb`;
let sql = '-- Global reference rows from production (no customer data).\n-- Generated by scripts/e2e/build-db.mjs. Do not edit by hand.\n\n';
const SKIP = new Set(['maintenance_templates']);
for (const [table, rows] of Object.entries(ref)) {
  if (!rows?.length || SKIP.has(table)) continue;
  sql += `insert into public.${table} select * from jsonb_populate_recordset(null::public.${table}, ${literal(rows)}) on conflict do nothing;\n\n`;
}
writeFileSync(`${OUT}/00000000000002_reference_data.sql`, sql);
console.log(`schema ${schema.length} bytes; reference tables: ${Object.entries(ref).map(([t, r]) => `${t}=${r?.length ?? 0}`).join(', ')}`);
